(1160578, 145075, 8284, '<td valign="top">Needs a better title.  Doesn''t convey pain to me.  Subject isn''t in focus, but the wall is.</td>', 'Needs a better title.  Doesn''t convey pain to me.  Subject isn''t in focus, but the wall is.', '2005-02-09 19:01:43.000000', NULL, 1),
(1160582, 144576, 33112, '<td valign="top">The eeriest thing about this photo is the little girl looking right at you.  Too bad the woman in the middle isn''t wearing a white shirt too.  I give it a 7.</td>', 'The eeriest thing about this photo is the little girl looking right at you.  Too bad the woman in the middle isn''t wearing a white shirt too.  I give it a 7.', '2005-02-09 19:02:04.000000', NULL, 1),
