(1161641, 145167, 14773, '<td valign="top">Without the title I wouldn''t have a clue what this is (one of the hazards of an international site I guess).</td>', 'Without the title I wouldn''t have a clue what this is (one of the hazards of an international site I guess).', '2005-02-10 12:23:16.000000', NULL, 1),
