(1161648, 143966, 8284, '<td valign="top">Like the title.  Nice image.  A little dark.</td>', 'Like the title.  Nice image.  A little dark.', '2005-02-10 12:30:46.000000', NULL, 1),
(1161652, 144961, 8284, '<td valign="top">Nice idea.  Would have worked better for me if the letter appeared to be more real.</td>', 'Nice idea.  Would have worked better for me if the letter appeared to be more real.', '2005-02-10 12:33:27.000000', NULL, 1),
(1161653, 143902, 31323, '<td valign="top">Not a big fan of the yellow, but good idea.  Would have maybe gotten a little more light on the pills.</td>', 'Not a big fan of the yellow, but good idea.  Would have maybe gotten a little more light on the pills.', '2005-02-10 12:33:37.000000', NULL, 1),
(1161654, 143555, 8284, '<td valign="top">This one works for me.  The expression seems just right for that instant when a smile changes to a grimace because the laugh causes pain.  The reds in the pic seem a little too strong.  Did you try this in B&amp;W?</td>', 'This one works for me.  The expression seems just right for that instant when a smile changes to a grimace because the laugh causes pain.  The reds in the pic seem a little too strong.  Did you try this in B&W?', '2005-02-10 12:35:19.000000', NULL, 1),
(1161656, 143084, 8284, '<td valign="top">Good title.  I like the feel of this pic, but the blown-out highlights are a little over the top for my taste.  Maybe with more contrast?  Nice shot overall.</td>', 'Good title.  I like the feel of this pic, but the blown-out highlights are a little over the top for my taste.  Maybe with more contrast?  Nice shot overall.', '2005-02-10 12:37:48.000000', NULL, 1),
(1161659, 144941, 20102, '<td valign="top">excellent idea, not-too-excellent production. Light is way off.</td>', 'excellent idea, not-too-excellent production. Light is way off.', '2005-02-10 12:39:19.000000', NULL, 1),
(1161664, 145138, 8284, '<td valign="top">I''d suggest looking for a way to make the scar just a little bit more obvious as the primary subject.  I like the drama of the lighting, but the lit areas are a little too bright, especially the throat.  Well-titled.</td>', 'I''d suggest looking for a way to make the scar just a little bit more obvious as the primary subject.  I like the drama of the lighting, but the lit areas are a little too bright, especially the throat.  Well-titled.', '2005-02-10 12:41:15.000000', NULL, 1),
(1161666, 143663, 8284, '<td valign="top">Good idea, but I think it begs for a human subject.  Nice soft feel to the pic.  B&amp;W is a good choice here.</td>', 'Good idea, but I think it begs for a human subject.  Nice soft feel to the pic.  B&W is a good choice here.', '2005-02-10 12:42:50.000000', NULL, 1),
(1161667, 144103, 33475, '<td valign="top">brilliant idea, altho very calm for someone who''s about to face pain. A solid white background would''ve been betteri think. Very good lighting coordination. but the best thing about the pic is her stunningly beautiful face.</td>', 'brilliant idea, altho very calm for someone who''s about to face pain. A solid white background would''ve been betteri think. Very good lighting coordination. but the best thing about the pic is her stunningly beautiful face.', '2005-02-10 12:43:34.000000', NULL, 1),
(1161669, 145030, 8284, '<td valign="top">I like the idea, but the image is too dark to make the blood stand out well.  Also doesn''t look like real blood to me.</td>', 'I like the idea, but the image is too dark to make the blood stand out well.  Also doesn''t look like real blood to me.', '2005-02-10 12:44:46.000000', NULL, 1),
(1161670, 143091, 8284, '<td valign="top">Too small.  Blurry.  Doesn''t even look that cold - no ice on the water.</td>', 'Too small.  Blurry.  Doesn''t even look that cold - no ice on the water.', '2005-02-10 12:45:47.000000', NULL, 1),
(1161672, 144605, 31323, '<td valign="top">Whoa,  I hope that is not YOUR balance.  Maybe would be better if the focused area was moved up more towards the center.  A little too much blurry space on the top, but don''t get me wrong, a very good picture (8)</td>', 'Whoa,  I hope that is not YOUR balance.  Maybe would be better if the focused area was moved up more towards the center.  A little too much blurry space on the top, but don''t get me wrong, a very good picture (8)', '2005-02-10 12:49:12.000000', NULL, 1),
