(1162028, 143781, 8284, '<td valign="top">Cute shot, but I don''t see the pain here.  Title doesn''t fit, either.  Otherwise, I like the image.</td>', 'Cute shot, but I don''t see the pain here.  Title doesn''t fit, either.  Otherwise, I like the image.', '2005-02-10 16:51:38.000000', NULL, 1),
(1162029, 144930, 8284, '<td valign="top">Nice idea, but this needs some perspective.  Very hard to tell what you''re looking at.</td>', 'Nice idea, but this needs some perspective.  Very hard to tell what you''re looking at.', '2005-02-10 16:52:36.000000', NULL, 1),
(1162032, 143413, 8284, '<td valign="top">I don''t see the connection between the image &amp; the  title, but I like the shot.  Dramatic.</td>', 'I don''t see the connection between the image & the  title, but I like the shot.  Dramatic.', '2005-02-10 16:54:02.000000', NULL, 1),
(1162035, 145029, 8284, '<td valign="top">Nicely composed.  The blood looks real, unlike most of the entries in this challenge.  The striking color of the red against the near-B&amp;W of the rest of the image adds a lot of punch.</td>', 'Nicely composed.  The blood looks real, unlike most of the entries in this challenge.  The striking color of the red against the near-B&W of the rest of the image adds a lot of punch.', '2005-02-10 16:57:37.000000', NULL, 1),
(1162037, 144170, 8284, '<td valign="top">Obviously a blood orange...</td>', 'Obviously a blood orange...', '2005-02-10 16:58:34.000000', NULL, 1),
(1162042, 143466, 8284, '<td valign="top">The makeup is too obvious.  Blotchy color on the skin, then sometimes B&amp;W.  Not enough blood from a wound like that.</td>', 'The makeup is too obvious.  Blotchy color on the skin, then sometimes B&W.  Not enough blood from a wound like that.', '2005-02-10 17:00:41.000000', NULL, 1),
(1162045, 145009, 8284, '<td valign="top">Extra points for documenting real pain.</td>', 'Extra points for documenting real pain.', '2005-02-10 17:03:13.000000', NULL, 1),
(1162059, 143084, 22734, '<td valign="top">This is an image with great potential. Personally I would have prefered color so as to give the tongue its more natural hue, only because it is the most outstanding part of the composition. However, outside of that minor observation this is indeed a very appropiate capture which exemplifies pain and discomfort. I take the desire to blow out some tones as part of a presentation effect and here we lean on the viewer to reconstruct these areas. The impact of the image is immediate. 6</td>', 'This is an image with great potential. Personally I would have prefered color so as to give the tongue its more natural hue, only because it is the most outstanding part of the composition. However, outside of that minor observation this is indeed a very appropiate capture which exemplifies pain and discomfort. I take the desire to blow out some tones as part of a presentation effect and here we lean on the viewer to reconstruct these areas. The impact of the image is immediate. 6', '2005-02-10 17:14:56.000000', NULL, 1),
(1162061, 144584, 2022, '<td valign="top">Very nice picture, I love its simplicity, the lighting is also interesting (9)<br/>Correction: bumping to 10.</td>', 'Very nice picture, I love its simplicity, the lighting is also interesting (9)Correction: bumping to 10.', '2005-02-10 17:15:33.000000', NULL, 1),
(1162088, 145170, 17505, '<td valign="top">Great use of contrasts and nice choice of black and white.<br/>This is a phot that anyone can like, and it still meets the criteria. <br/>I think you should do well.</td>', 'Great use of contrasts and nice choice of black and white.This is a phot that anyone can like, and it still meets the criteria. I think you should do well.', '2005-02-10 17:33:40.000000', NULL, 1),
(1162091, 144947, 17505, '<td valign="top">Beautiful! It''s probably going to get marked down for religious reasons, but technically it''s a very strong photo and I''m giving you my highest rating.</td>', 'Beautiful! It''s probably going to get marked down for religious reasons, but technically it''s a very strong photo and I''m giving you my highest rating.', '2005-02-10 17:35:11.000000', NULL, 1),
(1162094, 144913, 17505, '<td valign="top">Nice composition and I like your choice of sepia. <br/>I would like to see the face, but it''s still very strong without it.</td>', 'Nice composition and I like your choice of sepia. I would like to see the face, but it''s still very strong without it.', '2005-02-10 17:36:22.000000', NULL, 1),
(1162097, 143132, 17505, '<td valign="top">I''m afraid I don''t get it. It''s also out of focus and needs more contrast, it''s very busy in b&amp;w and hard to see anyhing.</td>', 'I''m afraid I don''t get it. It''s also out of focus and needs more contrast, it''s very busy in b&w and hard to see anyhing.', '2005-02-10 17:38:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1162100, 143118, 17505, '<td valign="top">As far as I can tell this has nothing to do with the competition...</td>', 'As far as I can tell this has nothing to do with the competition...', '2005-02-10 17:38:45.000000', NULL, 1),
(1162101, 145094, 17505, '<td valign="top">This has nothing to do with pain. <br/>Simply adding a title to tie the photo to the contest won''t change that.</td>', 'This has nothing to do with pain. Simply adding a title to tie the photo to the contest won''t change that.', '2005-02-10 17:39:39.000000', NULL, 1),
(1162104, 145102, 17505, '<td valign="top">I don''t see what this has to do with anything. I can''t tell what some of the shapes are due to the negative (?) effect. As far as I can see there isn''t any pain represented.</td>', 'I don''t see what this has to do with anything. I can''t tell what some of the shapes are due to the negative (?) effect. As far as I can see there isn''t any pain represented.', '2005-02-10 17:41:51.000000', NULL, 1),
(1162105, 143091, 31541, '<td valign="top">The picture is a bit too small to make out any details.</td>', 'The picture is a bit too small to make out any details.', '2005-02-10 17:41:57.000000', NULL, 1),
(1162108, 144626, 31541, '<td valign="top">Interesting picture.  There is something about it that attracts me, although I''m probably missing the symbolism.  The only comment I have is that the subjects hands blend in with the heart a little too much.</td>', 'Interesting picture.  There is something about it that attracts me, although I''m probably missing the symbolism.  The only comment I have is that the subjects hands blend in with the heart a little too much.', '2005-02-10 17:43:15.000000', NULL, 1),
(1162118, 143653, 31541, '<td valign="top">I really like the top portion of the picture.  The hand in the crotch area calls too much attention to itself (I''m assuming that the arm over the head was supposed to be the main focus of the picture).  I think it might look better if it was cropped around the belly button.</td>', 'I really like the top portion of the picture.  The hand in the crotch area calls too much attention to itself (I''m assuming that the arm over the head was supposed to be the main focus of the picture).  I think it might look better if it was cropped around the belly button.', '2005-02-10 17:47:16.000000', NULL, 1),
(1162123, 144670, 17505, '<td valign="top">Much too dark, unless you were going for a silhouette, in which case you need more difinition to teh figure. It''s also a little crooked, the room seems tilted to the right. It''s disorienting.</td>', 'Much too dark, unless you were going for a silhouette, in which case you need more difinition to teh figure. It''s also a little crooked, the room seems tilted to the right. It''s disorienting.', '2005-02-10 17:48:20.000000', NULL, 1),
(1162124, 145108, 31541, '<td valign="top">Nice photo.  Perhaps it would work a little better if the camera were shooting up toward the woman rather than down.  The floor is a little distracting.  She doesn''t looked too pained to me, though.</td>', 'Nice photo.  Perhaps it would work a little better if the camera were shooting up toward the woman rather than down.  The floor is a little distracting.  She doesn''t looked too pained to me, though.', '2005-02-10 17:49:13.000000', NULL, 1),
(1162127, 144930, 17505, '<td valign="top">I''m assuming that this is a scar, but it''s at such an odd angle that I can''t visualize it. I can''t even tell which part of the body I''m looking at. Sorry.</td>', 'I''m assuming that this is a scar, but it''s at such an odd angle that I can''t visualize it. I can''t even tell which part of the body I''m looking at. Sorry.', '2005-02-10 17:49:41.000000', NULL, 1),
(1162129, 143865, 17505, '<td valign="top">What''s the idea? He''s going to stab himself in the eye? Why? I don''t get it.</td>', 'What''s the idea? He''s going to stab himself in the eye? Why? I don''t get it.', '2005-02-10 17:50:53.000000', NULL, 1),
(1162130, 144584, 31541, '<td valign="top">Nice idea.  I wish there were better contrast - the subject blends in too much with the floor.</td>', 'Nice idea.  I wish there were better contrast - the subject blends in too much with the floor.', '2005-02-10 17:51:17.000000', NULL, 1),
(1162134, 145087, 28764, '<td valign="top">dd the kitty really got hurt?</td>', 'dd the kitty really got hurt?', '2005-02-10 17:52:53.000000', NULL, 1),
(1162136, 144339, 31541, '<td valign="top">This is my favorite pic so far from this challenge.  Great angle, focus and lighting!</td>', 'This is my favorite pic so far from this challenge.  Great angle, focus and lighting!', '2005-02-10 17:52:56.000000', NULL, 1),
(1162143, 144968, 31541, '<td valign="top">Ouch!  The borders are a bit distracting, and the focus seems a little off.</td>', 'Ouch!  The borders are a bit distracting, and the focus seems a little off.', '2005-02-10 17:54:10.000000', NULL, 1),
(1162150, 145123, 31541, '<td valign="top">Nice lighting and focus.  I think there is a little too much mascara running.  I''m wondering if the angle is a little too low also.</td>', 'Nice lighting and focus.  I think there is a little too much mascara running.  I''m wondering if the angle is a little too low also.', '2005-02-10 17:56:02.000000', NULL, 1),
(1162155, 143902, 17505, '<td valign="top">Strong photograph, but I don''t believe it shows pain. <br/>I''d also like the tablets to be in better focus.</td>', 'Strong photograph, but I don''t believe it shows pain. I''d also like the tablets to be in better focus.', '2005-02-10 17:57:20.000000', NULL, 1),
(1162156, 145139, 31541, '<td valign="top">The picture itself looks really good, but without some interaction it''s hard to see the pain.</td>', 'The picture itself looks really good, but without some interaction it''s hard to see the pain.', '2005-02-10 17:57:39.000000', NULL, 1),
(1162160, 143473, 31541, '<td valign="top">Normally, I''m not one for using toys in photos.  This one was done very well.  Lighting and focus are good, and the theme is great!</td>', 'Normally, I''m not one for using toys in photos.  This one was done very well.  Lighting and focus are good, and the theme is great!', '2005-02-10 17:58:21.000000', NULL, 1),
(1162166, 144138, 17505, '<td valign="top">I really like this phot, but I would have cropped his lower portion off. My eye is draws to the chain in teh lower rigth corner, I am tempted to look to see if he''s standing on something. If we couldn''t see anything but his stomach and higher I think this would not be an issue. Beautiful composition and lighting.</td>', 'I really like this phot, but I would have cropped his lower portion off. My eye is draws to the chain in teh lower rigth corner, I am tempted to look to see if he''s standing on something. If we couldn''t see anything but his stomach and higher I think this would not be an issue. Beautiful composition and lighting.', '2005-02-10 18:00:12.000000', NULL, 1),
(1162170, 144980, 31541, '<td valign="top">Nice picture!  Not sure I see the pain or sorrow, but I love the way the background came out!</td>', 'Nice picture!  Not sure I see the pain or sorrow, but I love the way the background came out!', '2005-02-10 18:00:54.000000', NULL, 1),
(1162173, 144795, 31541, '<td valign="top">Funny!  I''m wondering if including more of the front in this shot would have made more of an impact (i.e.  seeing the shoe bottom, side view of person and then partial leg of the person kicking).</td>', 'Funny!  I''m wondering if including more of the front in this shot would have made more of an impact (i.e.  seeing the shoe bottom, side view of person and then partial leg of the person kicking).', '2005-02-10 18:02:17.000000', NULL, 1),
(1162175, 143676, 31541, '<td valign="top">Nice idea.  The person seems a little too overexposed and "soft".</td>', 'Nice idea.  The person seems a little too overexposed and "soft".', '2005-02-10 18:03:19.000000', NULL, 1),
(1162178, 143132, 31541, '<td valign="top">Great picture (nice focus and texture), but I think I''m missing the reference to the theme.</td>', 'Great picture (nice focus and texture), but I think I''m missing the reference to the theme.', '2005-02-10 18:04:06.000000', NULL, 1),
(1162180, 145143, 31541, '<td valign="top">Cute picture, but where is the pain?</td>', 'Cute picture, but where is the pain?', '2005-02-10 18:04:33.000000', NULL, 1),
(1162183, 145061, 18799, '<td valign="top">Great take on this challenge.  Very emotive photograph.  Your DOF is perfect.  9</td>', 'Great take on this challenge.  Very emotive photograph.  Your DOF is perfect.  9', '2005-02-10 18:05:07.000000', NULL, 1),
(1162185, 144201, 31541, '<td valign="top">I like this picture.  Focus and lighting are good.  I wish that the subject were a little more off center, showing more of the room itself.  I think it would give it more of a "lonely" feeling.<br/>(There is a similar photo in this challenge to which I gave the same comment.)</td>', 'I like this picture.  Focus and lighting are good.  I wish that the subject were a little more off center, showing more of the room itself.  I think it would give it more of a "lonely" feeling.(There is a similar photo in this challenge to which I gave the same comment.)', '2005-02-10 18:06:27.000000', NULL, 1),
(1162191, 143392, 31541, '<td valign="top">Cute idea, but the picture is not lit very well.  It''s hard to make out the objects.</td>', 'Cute idea, but the picture is not lit very well.  It''s hard to make out the objects.', '2005-02-10 18:07:49.000000', NULL, 1),
(1162194, 144414, 31541, '<td valign="top">Nice photo - Like the DOF - you can see the pained look!  I hope this didn''t really happen to you.  The only suggestion I would make would be to remove the background hand, or darken the highlights - I think they detract a little from the picture.</td>', 'Nice photo - Like the DOF - you can see the pained look!  I hope this didn''t really happen to you.  The only suggestion I would make would be to remove the background hand, or darken the highlights - I think they detract a little from the picture.', '2005-02-10 18:09:42.000000', NULL, 1),
(1162197, 144427, 31541, '<td valign="top">Man, that is scary!  Not sure if hammer motion was meant to be shown in this pic.  It just looks out of focus rather than moving.</td>', 'Man, that is scary!  Not sure if hammer motion was meant to be shown in this pic.  It just looks out of focus rather than moving.', '2005-02-10 18:10:38.000000', NULL, 1),
(1162199, 145033, 31541, '<td valign="top">It''s hard to initially make out what is going on.  Perhaps moving the tray (if possible) would have helped.</td>', 'It''s hard to initially make out what is going on.  Perhaps moving the tray (if possible) would have helped.', '2005-02-10 18:11:23.000000', NULL, 1),
(1162207, 144848, 10268, '<td valign="top">Love the reflection.  Don''t love the background, though.  Composition is pretty good.  And the cut looks pretty real, although there''d be a ton of blood pouring out your veins.  Composition is good, too!  Maybe a little oversharpened, though.</td>', 'Love the reflection.  Don''t love the background, though.  Composition is pretty good.  And the cut looks pretty real, although there''d be a ton of blood pouring out your veins.  Composition is good, too!  Maybe a little oversharpened, though.', '2005-02-10 18:16:48.000000', NULL, 1),
(1162242, 144898, 31278, '<td valign="top">I think the coulor of this photo gives it an eerie feeling, though I wish I could see the fellow''s face.</td>', 'I think the coulor of this photo gives it an eerie feeling, though I wish I could see the fellow''s face.', '2005-02-10 18:38:28.000000', NULL, 1),
(1162243, 145123, 33473, '<td valign="top">Great contrast, clarity, and expression... but it really looks like you drew one her cheeks with eyeliner...</td>', 'Great contrast, clarity, and expression... but it really looks like you drew one her cheeks with eyeliner...', '2005-02-10 18:38:44.000000', NULL, 1),
(1162246, 145099, 13305, '<td valign="top">Well composed action shot. I wish you had a little more flash to illuminate the closest side of jumper.   Still high marks for good action freeze and treatment of the challenge.</td>', 'Well composed action shot. I wish you had a little more flash to illuminate the closest side of jumper.   Still high marks for good action freeze and treatment of the challenge.', '2005-02-10 18:39:38.000000', NULL, 1),
(1162250, 144993, 13305, '<td valign="top">The challenge is pain, not slapstick.   Try something less contrived.</td>', 'The challenge is pain, not slapstick.   Try something less contrived.', '2005-02-10 18:40:33.000000', NULL, 1),
(1162253, 144546, 31278, '<td valign="top"><br/><br/><i>Message edited by author 2008-01-16 15:30:10.</i></td>', '', '2005-02-10 18:41:33.000000', '2008-01-16 15:30:10.000000', 1),
(1162259, 145123, 13305, '<td valign="top">Interesting idea.  But "drawn in" tear tracks weakens the effect greatly.  Try again.</td>', 'Interesting idea.  But "drawn in" tear tracks weakens the effect greatly.  Try again.', '2005-02-10 18:44:05.000000', NULL, 1),
(1162264, 145061, 13305, '<td valign="top">Everyone likes to belong.  Great composition, nice bokeh, and the BW really adds to the reality of the situation.  Keep up the good workl.</td>', 'Everyone likes to belong.  Great composition, nice bokeh, and the BW really adds to the reality of the situation.  Keep up the good workl.', '2005-02-10 18:46:04.000000', NULL, 1),
(1162273, 144941, 13305, '<td valign="top">Good idea, poor execution.  <br/>1. The lighting is great, brings out the detail and draws the view to the center of the piece. <br/>2. The position of the hand is also great, looks like it''s contracted in pain.<br/>3. If you''re trying for religous conneciton, note that the nails were driven into Jesus'' hands and ankles, not wrist.  <br/>I still give you a 5 for the attempt. <br/></td>', 'Good idea, poor execution.  1. The lighting is great, brings out the detail and draws the view to the center of the piece. 2. The position of the hand is also great, looks like it''s contracted in pain.3. If you''re trying for religous conneciton, note that the nails were driven into Jesus'' hands and ankles, not wrist.  I still give you a 5 for the attempt. ', '2005-02-10 18:49:07.000000', NULL, 1),
(1162277, 144799, 13305, '<td valign="top">There is a distinct difference between physical pain undertaken willingly (piercings, tattoos, etc) and that which is incurred without asking for it (a broken bone etc.)</td>', 'There is a distinct difference between physical pain undertaken willingly (piercings, tattoos, etc) and that which is incurred without asking for it (a broken bone etc.)', '2005-02-10 18:51:30.000000', NULL, 1),
(1162286, 144103, 13305, '<td valign="top">Nice treatment of the challenge.  Great lighting and composition, the focus is spot on.</td>', 'Nice treatment of the challenge.  Great lighting and composition, the focus is spot on.', '2005-02-10 18:54:54.000000', NULL, 1),
(1162296, 143546, 13305, '<td valign="top">Now that looks like someone in pain. I like the contrast of lighting on her face and the darkness of the background.   I''d like a little more story in the picture though, what causes such pain for one so young and pretty?</td>', 'Now that looks like someone in pain. I like the contrast of lighting on her face and the darkness of the background.   I''d like a little more story in the picture though, what causes such pain for one so young and pretty?', '2005-02-10 18:57:14.000000', NULL, 1),
(1162340, 145077, 5898, '<td valign="top">Good job...I feel the pain!</td>', 'Good job...I feel the pain!', '2005-02-10 19:17:20.000000', NULL, 1),
(1162354, 145165, 5898, '<td valign="top">I really like the color, placement, and capturing the theme of pain. 9</td>', 'I really like the color, placement, and capturing the theme of pain. 9', '2005-02-10 19:25:18.000000', NULL, 1),
(1162359, 144834, 5898, '<td valign="top">This is really well done...I think the guy holding the light did a wonderful job.</td>', 'This is really well done...I think the guy holding the light did a wonderful job.', '2005-02-10 19:27:02.000000', NULL, 1),
(1162369, 143473, 33277, '<td valign="top">way to take this jokingly like i did, to many people are trying to be artistic.... good job</td>', 'way to take this jokingly like i did, to many people are trying to be artistic.... good job', '2005-02-10 19:32:48.000000', NULL, 1),
(1162370, 145074, 5898, '<td valign="top">I feel the pain, especially when you see the grade you get on this picture.</td>', 'I feel the pain, especially when you see the grade you get on this picture.', '2005-02-10 19:32:59.000000', NULL, 1),
(1162374, 144138, 33277, '<td valign="top">do some research on bondage photography, there ara alot of useful sites out there.  Get a new model that has better facial expression... But good try keep it up</td>', 'do some research on bondage photography, there ara alot of useful sites out there.  Get a new model that has better facial expression... But good try keep it up', '2005-02-10 19:34:46.000000', NULL, 1),
