(1162377, 145005, 33277, '<td valign="top">This shot was ok the first 25 times Ive seen this shot<br/></td>', 'This shot was ok the first 25 times Ive seen this shot', '2005-02-10 19:35:38.000000', NULL, 1),
(1162378, 144684, 33277, '<td valign="top">Nice idea. I like it but work on lighting.</td>', 'Nice idea. I like it but work on lighting.', '2005-02-10 19:36:39.000000', NULL, 1),
(1162379, 143473, 5898, '<td valign="top">After all the blood, I enjoyed the humor.</td>', 'After all the blood, I enjoyed the humor.', '2005-02-10 19:37:02.000000', NULL, 1),
(1162382, 143865, 33277, '<td valign="top">Unless your name is Luis Bunuel, stay away from razorblades in eyes.   Dont copy the greats...</td>', 'Unless your name is Luis Bunuel, stay away from razorblades in eyes.   Dont copy the greats...', '2005-02-10 19:38:08.000000', NULL, 1),
