(1162386, 143656, 33277, '<td valign="top">I love it... To many people are taking this one ultra serious.. I love it</td>', 'I love it... To many people are taking this one ultra serious.. I love it', '2005-02-10 19:41:07.000000', NULL, 1),
(1162389, 144947, 33277, '<td valign="top">Come on are you serious...</td>', 'Come on are you serious...', '2005-02-10 19:42:56.000000', NULL, 1),
(1162395, 144848, 33277, '<td valign="top">i like the reflection in the blade<br/></td>', 'i like the reflection in the blade', '2005-02-10 19:45:43.000000', NULL, 1),
(1162396, 145166, 5898, '<td valign="top">Excellent angle, you really captured the theme. The lighting also captures the mood of what you were trying to capture.</td>', 'Excellent angle, you really captured the theme. The lighting also captures the mood of what you were trying to capture.', '2005-02-10 19:46:28.000000', NULL, 1),
