(1163317, 145178, 29858, '<td valign="top">Very nice.  A little bit of pixelation around the thornes, but I''ll call that a problem from compression.  8.</td>', 'Very nice.  A little bit of pixelation around the thornes, but I''ll call that a problem from compression.  8.', '2005-02-11 10:33:34.000000', NULL, 1),
