(1163481, 145120, 27342, '<td valign="top">This is very funny.  An extra points for creativity.  Oh by the way.  I would have cropped the picture a bit to get rid of the electrical plates on the wall.  Just a little distracting.</td>', 'This is very funny.  An extra points for creativity.  Oh by the way.  I would have cropped the picture a bit to get rid of the electrical plates on the wall.  Just a little distracting.', '2005-02-11 11:57:43.000000', NULL, 1),
(1163488, 144971, 27342, '<td valign="top">This is a nice picture, however the child does not look at all sad, so the tear looks like it was intentionally placed.   Which I am sure it was, however if the child looked sadder and perhaps had watery eyes I would have given this a higher score.  Take the tear away and it''s a great potrait of the child.  points taken off for reasons stated above  I gave you a 6.</td>', 'This is a nice picture, however the child does not look at all sad, so the tear looks like it was intentionally placed.   Which I am sure it was, however if the child looked sadder and perhaps had watery eyes I would have given this a higher score.  Take the tear away and it''s a great potrait of the child.  points taken off for reasons stated above  I gave you a 6.', '2005-02-11 12:04:04.000000', NULL, 1),
(1163514, 143774, 24454, '<td valign="top">Ohmygoodness.   that hurts to looke at it.  Yikes.   Great depiction of pain!</td>', 'Ohmygoodness.   that hurts to looke at it.  Yikes.   Great depiction of pain!', '2005-02-11 12:20:19.000000', NULL, 1),
