(1164664, 145059, 21816, '<td valign="top">I can relate to this!!</td>', 'I can relate to this!!', '2005-02-12 02:03:46.000000', NULL, 1),
(1164679, 144103, 32464, '<td valign="top">Pain,a small price to pay for Beauty...</td>', 'Pain,a small price to pay for Beauty...', '2005-02-12 02:21:05.000000', NULL, 1),
(1164696, 145025, 32464, '<td valign="top">I am not so sure but wouldnt it be better if you were  closer to the subject (removing the shrubs), and bring flowers rather than a flag.. there is already one on the ground.No offence.</td>', 'I am not so sure but wouldnt it be better if you were  closer to the subject (removing the shrubs), and bring flowers rather than a flag.. there is already one on the ground.No offence.', '2005-02-12 02:34:46.000000', NULL, 1),
(1164712, 144500, 18799, '<td valign="top">I would have liked to have seen the composition adjusted so there is less negative space on the top.  Also, cutting the end of the ball and hand off hurts the image.</td>', 'I would have liked to have seen the composition adjusted so there is less negative space on the top.  Also, cutting the end of the ball and hand off hurts the image.', '2005-02-12 03:02:28.000000', NULL, 1),
(1164715, 144834, 32464, '<td valign="top">looks like we were thinking alike in some ways...Cheers.</td>', 'looks like we were thinking alike in some ways...Cheers.', '2005-02-12 03:07:51.000000', NULL, 1),
