INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1166588, 145159, 32659, '<td valign="top">The three drops on the page look like they were placed there as opposed to falling teardrops.</td>', 'The three drops on the page look like they were placed there as opposed to falling teardrops.', '2005-02-13 18:02:54.000000', NULL, 1),
(1166597, 144961, 13305, '<td valign="top">Painful yes, but the note is so out of focus, I couldn''t tell what it is without the title.</td>', 'Painful yes, but the note is so out of focus, I couldn''t tell what it is without the title.', '2005-02-13 18:15:10.000000', NULL, 1),
(1166598, 144888, 32659, '<td valign="top">The top of the pill blends into the background.</td>', 'The top of the pill blends into the background.', '2005-02-13 18:16:45.000000', NULL, 1),
(1166600, 145171, 13305, '<td valign="top">The body language of your subject is not that of someone in pain,   It''s more likely, he would be trying to withdraw from the world and curled up in a ball. good photo technique</td>', 'The body language of your subject is not that of someone in pain,   It''s more likely, he would be trying to withdraw from the world and curled up in a ball. good photo technique', '2005-02-13 18:17:33.000000', NULL, 1),
(1166605, 144141, 32659, '<td valign="top">If it wasn''t for the title, I wouldn''t have known this was the losing team.</td>', 'If it wasn''t for the title, I wouldn''t have known this was the losing team.', '2005-02-13 18:19:15.000000', NULL, 1),
(1166606, 143490, 13305, '<td valign="top">Good composition, good use of natural light. The pain of loss is easily felt.  I think I might have cropped n a bit closer on the subject.  The background is a bit cluttered.</td>', 'Good composition, good use of natural light. The pain of loss is easily felt.  I think I might have cropped n a bit closer on the subject.  The background is a bit cluttered.', '2005-02-13 18:20:37.000000', NULL, 1),
(1166609, 144901, 32659, '<td valign="top">Praying is pain?</td>', 'Praying is pain?', '2005-02-13 18:22:02.000000', NULL, 1),
(1166611, 143843, 13305, '<td valign="top">Kitty looks more whimsical than in pain, but not a bad pic of a cat.</td>', 'Kitty looks more whimsical than in pain, but not a bad pic of a cat.', '2005-02-13 18:22:44.000000', NULL, 1),
(1166638, 143511, 12998, '<td valign="top">tooo fuzzy</td>', 'tooo fuzzy', '2005-02-13 18:47:07.000000', NULL, 1),
(1166673, 144947, 6600, '<td valign="top">This would have done well in the Movie challenge as well.  Excellent job!</td>', 'This would have done well in the Movie challenge as well.  Excellent job!', '2005-02-13 19:09:48.000000', NULL, 1),
(1166675, 145177, 6600, '<td valign="top">Feelings of sadness look genuine, like the grayscale, nicely framed, excellent job.</td>', 'Feelings of sadness look genuine, like the grayscale, nicely framed, excellent job.', '2005-02-13 19:10:55.000000', NULL, 1),
(1166678, 144898, 6600, '<td valign="top">Nice capture, like the tones, great job.  (I can''t make myself take shots like this, would make me feel guilty and exploitive.)</td>', 'Nice capture, like the tones, great job.  (I can''t make myself take shots like this, would make me feel guilty and exploitive.)', '2005-02-13 19:14:43.000000', NULL, 1),
(1166680, 145168, 6600, '<td valign="top">Very emotive, realistic, has a genuine look about it.  Super job!!  (May be a bit dark, but I think it works with the emotions/feelings being conveyed)</td>', 'Very emotive, realistic, has a genuine look about it.  Super job!!  (May be a bit dark, but I think it works with the emotions/feelings being conveyed)', '2005-02-13 19:17:24.000000', NULL, 1),
