(1167842, 144993, 14656, '<td valign="top">While this could be painful, I do not get the sense of the hammer being driven into the man''s skull. It looks too stationary and setup. Probably photographing the hammer slightly blurred from motion, right before the moment of impact would imply more pain.</td>', 'While this could be painful, I do not get the sense of the hammer being driven into the man''s skull. It looks too stationary and setup. Probably photographing the hammer slightly blurred from motion, right before the moment of impact would imply more pain.', '2005-02-14 04:47:25.000000', NULL, 1),
(1167844, 143392, 14656, '<td valign="top">I''m not feeling the colors or lighting here.</td>', 'I''m not feeling the colors or lighting here.', '2005-02-14 04:48:06.000000', NULL, 1),
(1167845, 144942, 14656, '<td valign="top">Pretty busy photograph. Took me a good while to find the girl covering her ears and probably would''ve never noticed it without reading the title.</td>', 'Pretty busy photograph. Took me a good while to find the girl covering her ears and probably would''ve never noticed it without reading the title.', '2005-02-14 04:48:58.000000', NULL, 1),
