(1167857, 144845, 14656, '<td valign="top">Mmm.. this makes me hungry. Your kitty has cute eyes.</td>', 'Mmm.. this makes me hungry. Your kitty has cute eyes.', '2005-02-14 04:51:58.000000', NULL, 1),
(1167860, 144892, 14656, '<td valign="top">Looks slightly out of focus and oversharpened to compensate. Good idea, could do with less chain from the top and a slightly tighter crop on the apple and hardware.</td>', 'Looks slightly out of focus and oversharpened to compensate. Good idea, could do with less chain from the top and a slightly tighter crop on the apple and hardware.', '2005-02-14 04:52:53.000000', NULL, 1),
(1167863, 145025, 14656, '<td valign="top">"Model" doesn''t look very natural and seems too posed and stiff. A tighter crop to eliminate the distracting background and focus more on his emotion would''ve been more effective IMO.</td>', '"Model" doesn''t look very natural and seems too posed and stiff. A tighter crop to eliminate the distracting background and focus more on his emotion would''ve been more effective IMO.', '2005-02-14 04:54:41.000000', NULL, 1),
