(1167868, 145171, 14656, '<td valign="top">Good processing. Border a little heavy. Wish the face was slightly brighter.</td>', 'Good processing. Border a little heavy. Wish the face was slightly brighter.', '2005-02-14 04:57:07.000000', NULL, 1),
