(1168921, 145165, 12253, '<td valign="top">Very nice!   Really painterly, very good symbolism for pain.<br/> <br/>I can''t wait to see how this was done within the rules!  (I guess something to do with printing first..) <br/> <br/>Bumping up.</td>', 'Very nice!   Really painterly, very good symbolism for pain. I can''t wait to see how this was done within the rules!  (I guess something to do with printing first..)  Bumping up.', '2005-02-14 14:29:15.000000', NULL, 1),
(1168931, 143413, 29739, '<td valign="top">It really transmits the pain, I like the lights and the lost sight begging the pain to stop. Toothache? ;)</td>', 'It really transmits the pain, I like the lights and the lost sight begging the pain to stop. Toothache? ;)', '2005-02-14 14:37:54.000000', NULL, 1),
(1169009, 143118, 32409, '<td valign="top">The mouse is quite pixelated. The colors are unappealing. This seems like an honest attempt at a brown ribbon. - 10</td>', 'The mouse is quite pixelated. The colors are unappealing. This seems like an honest attempt at a brown ribbon. - 10', '2005-02-14 15:25:04.000000', NULL, 1),
(1169010, 143983, 32409, '<td valign="top">I really liked this picture. I like the use of negative space as well as the orientation. It seems more honest than a lot of the "pain from the studio" in this challenge.</td>', 'I really liked this picture. I like the use of negative space as well as the orientation. It seems more honest than a lot of the "pain from the studio" in this challenge.', '2005-02-14 15:27:07.000000', NULL, 1),
(1169014, 144762, 33560, '<td valign="top">Psychic pain can be as profound as physical pain and it can be more debilitating than all but the worst physical pain.  This photo captures the psychic pain of a young person very well.  The lighting is strong and moody.  The photo is nicely cropped.  The subjects large and expressive eyes are perfectly framed by the rest of the composition.  The photo does have a distraction, that wedge of unexplained material that blocks off the subject''s mounth and cheek. Is it a chair? A window frame? A doorstop? A cello?  This leads us away from the subject</td>', 'Psychic pain can be as profound as physical pain and it can be more debilitating than all but the worst physical pain.  This photo captures the psychic pain of a young person very well.  The lighting is strong and moody.  The photo is nicely cropped.  The subjects large and expressive eyes are perfectly framed by the rest of the composition.  The photo does have a distraction, that wedge of unexplained material that blocks off the subject''s mounth and cheek. Is it a chair? A window frame? A doorstop? A cello?  This leads us away from the subject', '2005-02-14 15:28:27.000000', NULL, 1),
(1169016, 143656, 32409, '<td valign="top">I would say this is one of my favorites for this contest. I like the sepia tone. I think that the bandaid is a little bit blown out, but I still feel that it doesn''t detract from the picture.</td>', 'I would say this is one of my favorites for this contest. I like the sepia tone. I think that the bandaid is a little bit blown out, but I still feel that it doesn''t detract from the picture.', '2005-02-14 15:28:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1169018, 144657, 33560, '<td valign="top">A pretty photo, but at this size it''s unclear that we are looking at an aphid being eaten by a ladybug - if indeed that is the subject.</td>', 'A pretty photo, but at this size it''s unclear that we are looking at an aphid being eaten by a ladybug - if indeed that is the subject.', '2005-02-14 15:30:24.000000', NULL, 1),
(1169024, 143173, 32409, '<td valign="top">This is a great picture. Unlike all the other graveyard pictures, you didn''t ruin it by putting people in it. Death speaks for itself. Arlington always lends itself to spooky/painful pictures. Well captured. But I would have liked to see only one edge lacking vanishing points in this picture instead of two.</td>', 'This is a great picture. Unlike all the other graveyard pictures, you didn''t ruin it by putting people in it. Death speaks for itself. Arlington always lends itself to spooky/painful pictures. Well captured. But I would have liked to see only one edge lacking vanishing points in this picture instead of two.', '2005-02-14 15:32:36.000000', NULL, 1),
(1169031, 145122, 32409, '<td valign="top">People are going to hate this picture. Some may even call PETA. That being said: I love it. It seems well enough appropriate in that pain is not a pretty thing. I like how the mouse is brought to the focus with the blurred background and the appropriate highlighting at the focus. One of my top for this challenge.</td>', 'People are going to hate this picture. Some may even call PETA. That being said: I love it. It seems well enough appropriate in that pain is not a pretty thing. I like how the mouse is brought to the focus with the blurred background and the appropriate highlighting at the focus. One of my top for this challenge.', '2005-02-14 15:36:08.000000', NULL, 1),
(1169042, 143653, 33671, '<td valign="top">I like the photograph, but it doesn''t say ''pain'' to me. I like the lighting and pose. Not sure  I like the lower legs being cropped out.</td>', 'I like the photograph, but it doesn''t say ''pain'' to me. I like the lighting and pose. Not sure  I like the lower legs being cropped out.', '2005-02-14 15:39:22.000000', NULL, 1),
(1169043, 145061, 33560, '<td valign="top">Being laughed at - it is frequently more painful than sticks and stones: so there is a considerable amount of irony and some cruelty in the old ditty.  This photo instantly evokes this idea.  The bokeh is perfectly suited to the subject; less would cause us to be confused about the subject, but more would cause us to miss the sneering laughter of the people in the background.  Hollywood would cast a more photogenic person as the hero - someone more people could identify with - but the casting here seems more natural, more realistic.  <br/> <br/>In a kind of photojournalistic sense this photo is almost flawless.  Yet somehow it lacks a ''come hither'' sensibility, a prettyness or photographic elegance.  A really good effort!</td>', 'Being laughed at - it is frequently more painful than sticks and stones: so there is a considerable amount of irony and some cruelty in the old ditty.  This photo instantly evokes this idea.  The bokeh is perfectly suited to the subject; less would cause us to be confused about the subject, but more would cause us to miss the sneering laughter of the people in the background.  Hollywood would cast a more photogenic person as the hero - someone more people could identify with - but the casting here seems more natural, more realistic.   In a kind of photojournalistic sense this photo is almost flawless.  Yet somehow it lacks a ''come hither'' sensibility, a prettyness or photographic elegance.  A really good effort!', '2005-02-14 15:39:27.000000', NULL, 1),
(1169046, 145120, 33671, '<td valign="top">Fun concept, but poor execution. The masking around the hair is poor. The floor on the right is also visually distracting.</td>', 'Fun concept, but poor execution. The masking around the hair is poor. The floor on the right is also visually distracting.', '2005-02-14 15:39:50.000000', NULL, 1),
(1169051, 144625, 32409, '<td valign="top">I feel that you are going well over everyone''s heads on this one - no one likes SAT words, or non-centered, large borders. I really like it. I think that the expression on the model''s face is absolutely perfect to illustrate illiteracy. It is well framed but the handwriting is a little too good for someone illiterate, and c''mon, who marries someone who can''t read?!? The ring should have come off for this one... Still one of my top 10.</td>', 'I feel that you are going well over everyone''s heads on this one - no one likes SAT words, or non-centered, large borders. I really like it. I think that the expression on the model''s face is absolutely perfect to illustrate illiteracy. It is well framed but the handwriting is a little too good for someone illiterate, and c''mon, who marries someone who can''t read?!? The ring should have come off for this one... Still one of my top 10.', '2005-02-14 15:41:23.000000', NULL, 1),
(1169058, 143039, 32409, '<td valign="top">Even though this looks like it was staged for this challenge, it seems a bit more honest and candid than the others. The hair on the model''s face is a really nice touch. Seems like it was touched up very well.</td>', 'Even though this looks like it was staged for this challenge, it seems a bit more honest and candid than the others. The hair on the model''s face is a really nice touch. Seems like it was touched up very well.', '2005-02-14 15:43:29.000000', NULL, 1),
(1169063, 144892, 32409, '<td valign="top">I really like this picture. I think a little larger DOF would allow the front screw to be totally in focus. Definitely in my top ten though.</td>', 'I really like this picture. I think a little larger DOF would allow the front screw to be totally in focus. Definitely in my top ten though.', '2005-02-14 15:44:49.000000', NULL, 1),
(1169065, 144952, 33560, '<td valign="top">So, is this a kind of ''I need to call the President but I''m out of quarters'' pain of Dr. Strangelove vintage or ''I can''t believe what I''m hearing at the other end of the line'' kind of pain?  The question makes the photo more interesting.  It''s an interesting concept and, for the most part, it is nicely executed - the motion of the receiver, the wrinkles in the jeans, the open hand, the wedding ring.  But I find it annoying or distracting that the line of the work surface passed through the hand.  It strips the hand of most of its expressive power.  <br/></td>', 'So, is this a kind of ''I need to call the President but I''m out of quarters'' pain of Dr. Strangelove vintage or ''I can''t believe what I''m hearing at the other end of the line'' kind of pain?  The question makes the photo more interesting.  It''s an interesting concept and, for the most part, it is nicely executed - the motion of the receiver, the wrinkles in the jeans, the open hand, the wedding ring.  But I find it annoying or distracting that the line of the work surface passed through the hand.  It strips the hand of most of its expressive power.  ', '2005-02-14 15:45:36.000000', NULL, 1),
(1169066, 145170, 5237, '<td valign="top">gr8! photo! i like youre composition!!   congrats!</td>', 'gr8! photo! i like youre composition!!   congrats!', '2005-02-14 15:46:00.000000', NULL, 1),
(1169071, 144389, 32409, '<td valign="top">Even though this picture is one of the "obvious studio pain fakes" in this challenge, I find it very intriguing. The look on the model''s face looks like pure determination. When it looks like you''re attempting to cut your face off, I''m gonna guess that''s the look you get in your eyes. One of the top, in my opinion.</td>', 'Even though this picture is one of the "obvious studio pain fakes" in this challenge, I find it very intriguing. The look on the model''s face looks like pure determination. When it looks like you''re attempting to cut your face off, I''m gonna guess that''s the look you get in your eyes. One of the top, in my opinion.', '2005-02-14 15:47:31.000000', NULL, 1),
(1169077, 144414, 32409, '<td valign="top">I really like the depth of field, as well as the idea for the picture. I feel the colors could use a little bit of adjustment. Maybe just a curves adjustment. Also the tips of the fingers are a little washed out in places.</td>', 'I really like the depth of field, as well as the idea for the picture. I feel the colors could use a little bit of adjustment. Maybe just a curves adjustment. Also the tips of the fingers are a little washed out in places.', '2005-02-14 15:49:32.000000', NULL, 1),
(1169086, 145032, 32409, '<td valign="top">I''m a fan of this picture. If only this were an advanced editing challenge, you would have this in the bag. The bird''s face isn''t that detailed and a little dark. Burning and dodging would allow this picture to shine.</td>', 'I''m a fan of this picture. If only this were an advanced editing challenge, you would have this in the bag. The bird''s face isn''t that detailed and a little dark. Burning and dodging would allow this picture to shine.', '2005-02-14 15:51:29.000000', NULL, 1),
(1169089, 144898, 32409, '<td valign="top">Very nice use of sepia here. I like the simplicity of the photo outside of the subject and how it sort of frames itself inside the photo. One of my top ten.</td>', 'Very nice use of sepia here. I like the simplicity of the photo outside of the subject and how it sort of frames itself inside the photo. One of my top ten.', '2005-02-14 15:52:29.000000', NULL, 1),
(1169093, 144576, 33560, '<td valign="top">The composition is tight, the lighting is moody, the exposure is right-on. There''s a nice tension between the dead, the live, and the ghosts (live persons reflected in the casket.) I like this photo very much, but to my sensibility, only two characters seem to display touching, photogenic human emotion: the woman in the striped shirt and the little girl just to the right of her in the photo.  Impossible to catch without a longer lens, I suppose.</td>', 'The composition is tight, the lighting is moody, the exposure is right-on. There''s a nice tension between the dead, the live, and the ghosts (live persons reflected in the casket.) I like this photo very much, but to my sensibility, only two characters seem to display touching, photogenic human emotion: the woman in the striped shirt and the little girl just to the right of her in the photo.  Impossible to catch without a longer lens, I suppose.', '2005-02-14 15:53:51.000000', NULL, 1),
(1169094, 144795, 32409, '<td valign="top">Good idea. Very simple. Even though this would be nice to see some more "push" from the foot onto the crotch, I like this. The foot does seem just incidentally placed between the legs. I would like to see more action out of this pain. But obviously, no one is willing to get squared like this for a DPC photo. (And if they do, you''ve got good friends.)</td>', 'Good idea. Very simple. Even though this would be nice to see some more "push" from the foot onto the crotch, I like this. The foot does seem just incidentally placed between the legs. I would like to see more action out of this pain. But obviously, no one is willing to get squared like this for a DPC photo. (And if they do, you''ve got good friends.)', '2005-02-14 15:55:21.000000', NULL, 1),
(1169098, 144963, 32409, '<td valign="top">You''re going to get torn up in the voting for submitting such a small photo. I liked it. I gave it a seven. I don''t think it needs to be large to convey the idea. I like the selective desaturation and the bright yellow of the bandaid. Good picture. Know this would have placed higher if it were larger.</td>', 'You''re going to get torn up in the voting for submitting such a small photo. I liked it. I gave it a seven. I don''t think it needs to be large to convey the idea. I like the selective desaturation and the bright yellow of the bandaid. Good picture. Know this would have placed higher if it were larger.', '2005-02-14 15:57:12.000000', NULL, 1),
(1169101, 143132, 33560, '<td valign="top">Does a live tree feel pain? Does a live cockroach feel pain?  Does a rock? Does a dead tree?  I love photos of dead trees as much as the next guy.  In fact, I hardly ever pass up an opportunity to photograph one;  yet I''m skeptical that this photo is about pain.  Unless its our pain on the loss of a perfectly good tree, in which case I''d expect to see a tree fallen in its prime.  It''s a pretty good shot of a pretty photogenic tree, but the background is just a little too distracting  - especially tha tree that''s behind the right branch.</td>', 'Does a live tree feel pain? Does a live cockroach feel pain?  Does a rock? Does a dead tree?  I love photos of dead trees as much as the next guy.  In fact, I hardly ever pass up an opportunity to photograph one;  yet I''m skeptical that this photo is about pain.  Unless its our pain on the loss of a perfectly good tree, in which case I''d expect to see a tree fallen in its prime.  It''s a pretty good shot of a pretty photogenic tree, but the background is just a little too distracting  - especially tha tree that''s behind the right branch.', '2005-02-14 15:58:56.000000', NULL, 1),
(1169103, 144339, 32409, '<td valign="top">Most of the studio pictures in this challenge were terrible. The poses were unnatural and the expressions were hokie. This is not one of those pictures. The colors are good. Sharp as it needs to be. I only find the back part of the left arm that seems to be floating in the background as a distraction. You can''t ask for everything. One of the tops in my opinion.</td>', 'Most of the studio pictures in this challenge were terrible. The poses were unnatural and the expressions were hokie. This is not one of those pictures. The colors are good. Sharp as it needs to be. I only find the back part of the left arm that seems to be floating in the background as a distraction. You can''t ask for everything. One of the tops in my opinion.', '2005-02-14 16:00:31.000000', NULL, 1),
(1169104, 144584, 33560, '<td valign="top">The actor who struts and frets across the stage full of sound and fury signifying nothing.  To the extent that there is pain in nothingness, it''s here.  Otherwise we remain unconvinced.</td>', 'The actor who struts and frets across the stage full of sound and fury signifying nothing.  To the extent that there is pain in nothingness, it''s here.  Otherwise we remain unconvinced.', '2005-02-14 16:01:25.000000', NULL, 1),
(1169108, 145178, 32409, '<td valign="top">I like the detail in this picture. The lighting is very good, as well as the backgound color selection. I don''t mind the border, but usually pictures with borders this big get voted lower.</td>', 'I like the detail in this picture. The lighting is very good, as well as the backgound color selection. I don''t mind the border, but usually pictures with borders this big get voted lower.', '2005-02-14 16:02:55.000000', NULL, 1),
(1169109, 144103, 33560, '<td valign="top">The pains we take to make others yearn for us - to inflict the pain of jealousy and envy - on those closest to ourselves.  Yes.  Perhaps the pain is more than that little pin prick when the hair comes out. Perhaps the damage is more than skin deep.  A beautiful photo, clearly apropos to the subject, yet not perfectly obvious.</td>', 'The pains we take to make others yearn for us - to inflict the pain of jealousy and envy - on those closest to ourselves.  Yes.  Perhaps the pain is more than that little pin prick when the hair comes out. Perhaps the damage is more than skin deep.  A beautiful photo, clearly apropos to the subject, yet not perfectly obvious.', '2005-02-14 16:04:01.000000', NULL, 1),
(1169112, 144895, 32409, '<td valign="top">Very good picture. I think the lighting with the smoke works very well. I don''t like all the little white specks you can see in the foreground. I think this would work a lot better if you took the foreground out of the picture entirely and had a bullet, smoke and negative space.</td>', 'Very good picture. I think the lighting with the smoke works very well. I don''t like all the little white specks you can see in the foreground. I think this would work a lot better if you took the foreground out of the picture entirely and had a bullet, smoke and negative space.', '2005-02-14 16:05:06.000000', NULL, 1),
(1169115, 144980, 33560, '<td valign="top">Brr! Very funny. Nice shot.  Oh, I almost missed your meaning, you were referring to the missing fingers!</td>', 'Brr! Very funny. Nice shot.  Oh, I almost missed your meaning, you were referring to the missing fingers!', '2005-02-14 16:06:13.000000', NULL, 1),
(1169120, 144888, 32409, '<td valign="top">I think this is a good macro of a tylenol pill. You will probably get a lot of "too white" comments, but I think it suits the subject very well. If you''re going to do white, why not go big, or go home?!? Could maybe use some sharpening, though, to bring out that band around the pill.</td>', 'I think this is a good macro of a tylenol pill. You will probably get a lot of "too white" comments, but I think it suits the subject very well. If you''re going to do white, why not go big, or go home?!? Could maybe use some sharpening, though, to bring out that band around the pill.', '2005-02-14 16:07:40.000000', NULL, 1),
(1169123, 145010, 33560, '<td valign="top">Don''t you just hate it when people spill the ketchup on the counter.  Sometimes towells aren''t enough and you have to go after it with a kitchen knife.  Would be just a bit more convincing if you couldn''t actually see the finger doubled under.  I like the gleam of the knife.</td>', 'Don''t you just hate it when people spill the ketchup on the counter.  Sometimes towells aren''t enough and you have to go after it with a kitchen knife.  Would be just a bit more convincing if you couldn''t actually see the finger doubled under.  I like the gleam of the knife.', '2005-02-14 16:08:45.000000', NULL, 1),
(1169125, 144892, 33560, '<td valign="top">Post no signs.</td>', 'Post no signs.', '2005-02-14 16:09:13.000000', NULL, 1),
(1169126, 145059, 32409, '<td valign="top">It''s probably not going to hurt as bad as the score for this picture.</td>', 'It''s probably not going to hurt as bad as the score for this picture.', '2005-02-14 16:09:22.000000', NULL, 1),
(1169132, 145123, 33560, '<td valign="top">The lighting and exposure are perfect.  The veil is a pretty touch.  Does anybody else find the black drawing on the face distracting?  Or that little bump on the upper lip?</td>', 'The lighting and exposure are perfect.  The veil is a pretty touch.  Does anybody else find the black drawing on the face distracting?  Or that little bump on the upper lip?', '2005-02-14 16:11:41.000000', NULL, 1),
(1169134, 145030, 33560, '<td valign="top">I''m afraid I just see red when people try to equate blood with pain.  Nice strong lighting.</td>', 'I''m afraid I just see red when people try to equate blood with pain.  Nice strong lighting.', '2005-02-14 16:13:47.000000', NULL, 1),
(1169135, 144732, 26679, '<td valign="top">I am aware that that the Eagles lost but as an European, the word Philly in the title does not help with this I''m afraid.<br/> <br/>The image in the paper shows a guy holding a ball, he could be a winner or a looser....<br/> <br/>The idea is good, but this is an international challenge, so not everone will be familiar with the Superbowl, just like most of your countrymen  will not be aware about the FA cup</td>', 'I am aware that that the Eagles lost but as an European, the word Philly in the title does not help with this I''m afraid. The image in the paper shows a guy holding a ball, he could be a winner or a looser.... The idea is good, but this is an international challenge, so not everone will be familiar with the Superbowl, just like most of your countrymen  will not be aware about the FA cup', '2005-02-14 16:14:09.000000', NULL, 1),
(1169136, 144642, 33560, '<td valign="top">Here, the pain lies in the viewer, presumably.</td>', 'Here, the pain lies in the viewer, presumably.', '2005-02-14 16:14:48.000000', NULL, 1),
(1169138, 144684, 33560, '<td valign="top">Ouch!  The whisp of smoke was the master-stroke.  Clever composition, you even got a hand that looks fragile.  Nice lighting.</td>', 'Ouch!  The whisp of smoke was the master-stroke.  Clever composition, you even got a hand that looks fragile.  Nice lighting.', '2005-02-14 16:18:07.000000', NULL, 1),
(1169139, 145120, 33560, '<td valign="top">Very droll.</td>', 'Very droll.', '2005-02-14 16:18:25.000000', NULL, 1),
(1169141, 143656, 33560, '<td valign="top">Sometimes the pain comes from viewing someone else''s hairy buttocks.</td>', 'Sometimes the pain comes from viewing someone else''s hairy buttocks.', '2005-02-14 16:20:04.000000', NULL, 1),
(1169145, 144998, 33560, '<td valign="top">Nice try, but the acting seems unconvincing.</td>', 'Nice try, but the acting seems unconvincing.', '2005-02-14 16:21:09.000000', NULL, 1),
(1169146, 144799, 33560, '<td valign="top">Very convincing.  And well shot. I am repulsed.</td>', 'Very convincing.  And well shot. I am repulsed.', '2005-02-14 16:22:01.000000', NULL, 1),
(1169149, 145061, 17507, '<td valign="top">one of the better ones I have come across so far.<br/>too bad basic editing rules prevent burning... hot spot at the top is distracting. <br/>great work, though. (8)<br/>oop- coming back to bump to 9. this is one of my favorite 3 in the challenge, despite the technical issue I mentioned above. Aside from that one spot, the composition is great, and this more clearly conveys the *emotion* of pain than any other image in this challenge.</td>', 'one of the better ones I have come across so far.too bad basic editing rules prevent burning... hot spot at the top is distracting. great work, though. (8)oop- coming back to bump to 9. this is one of my favorite 3 in the challenge, despite the technical issue I mentioned above. Aside from that one spot, the composition is great, and this more clearly conveys the *emotion* of pain than any other image in this challenge.', '2005-02-14 16:23:32.000000', NULL, 1),
(1169154, 145171, 17507, '<td valign="top">Very strong entry. Colors and tones are fabulous- muted with hints of red are very appropriate. One of my favorites from this challenge.</td>', 'Very strong entry. Colors and tones are fabulous- muted with hints of red are very appropriate. One of my favorites from this challenge.', '2005-02-14 16:24:19.000000', NULL, 1),
(1169156, 145029, 17507, '<td valign="top">Very strong entry- quite suggestive. Unusual composition works well. One of my favorites from this challenge.</td>', 'Very strong entry- quite suggestive. Unusual composition works well. One of my favorites from this challenge.', '2005-02-14 16:24:45.000000', NULL, 1),
(1169157, 144947, 33560, '<td valign="top">King of pain.  Sometimes one wonders whether contemplating the passion has not caused enough pain.  It''s an effective shot, though it seems somehow self-conscious.</td>', 'King of pain.  Sometimes one wonders whether contemplating the passion has not caused enough pain.  It''s an effective shot, though it seems somehow self-conscious.', '2005-02-14 16:25:40.000000', NULL, 1),
(1169163, 143676, 33560, '<td valign="top">The shot is a little cluttered.  The lighting is spooky and strange. The subject, though sharply focussed is mostly on the wrong side of the light and so is hard to see.  The picture itself strikes me as being messy, unkempt, hard to make out.  But the story it tells is touching.  A man travelling to see loved ones who have not come to pick him up.  It is a powerful story.   The photo is about a 3.  The story is about a 9.</td>', 'The shot is a little cluttered.  The lighting is spooky and strange. The subject, though sharply focussed is mostly on the wrong side of the light and so is hard to see.  The picture itself strikes me as being messy, unkempt, hard to make out.  But the story it tells is touching.  A man travelling to see loved ones who have not come to pick him up.  It is a powerful story.   The photo is about a 3.  The story is about a 9.', '2005-02-14 16:29:45.000000', NULL, 1),
(1169166, 144184, 33560, '<td valign="top">There is a difference between pain and revulsion; about 3 points.</td>', 'There is a difference between pain and revulsion; about 3 points.', '2005-02-14 16:30:48.000000', NULL, 1),
(1169172, 144567, 26679, '<td valign="top">This is a superb Architectural photograph, unfortunatly the link to pain has passed me by.</td>', 'This is a superb Architectural photograph, unfortunatly the link to pain has passed me by.', '2005-02-14 16:33:45.000000', NULL, 1),
(1169173, 144993, 33560, '<td valign="top">Reminiscent of the Steve Martin stand up routine in which he comes out and does a whole routine with an arrow through his head - never a mentio of the arrow.  It''s a cute shot, clever, funny, thematic.  But it seems uncompelling.</td>', 'Reminiscent of the Steve Martin stand up routine in which he comes out and does a whole routine with an arrow through his head - never a mentio of the arrow.  It''s a cute shot, clever, funny, thematic.  But it seems uncompelling.', '2005-02-14 16:34:22.000000', NULL, 1),
(1169174, 145170, 26679, '<td valign="top">Visual simplicity and straight to the point......</td>', 'Visual simplicity and straight to the point......', '2005-02-14 16:34:24.000000', NULL, 1),
(1169175, 145102, 33560, '<td valign="top">A very cute pig.</td>', 'A very cute pig.', '2005-02-14 16:34:58.000000', NULL, 1),
